export default function ServiceDetailsFields({defaults}:{defaults?:{serviceInclusions?:string|null;serviceRequirements?:string|null;serviceDeliverables?:string|null}}){return <section data-creation-section="Customer expectations" className="rounded-2xl border border-sky-100 bg-white p-5"><h3 className="text-sm font-bold text-[#174766]">Make the offer clear</h3><p className="mb-5 mt-1 text-xs leading-5 text-slate-500">These details appear on the service page before the customer makes a request. Use plain language and avoid asking for sensitive personal information.</p><div className="grid gap-5">{SERVICE_OFFER_FIELDS.map(f=><label key={f.name} className="grid gap-2 text-xs font-semibold text-slate-700">{f.label}<textarea name={f.name} defaultValue={defaults?.[f.name as keyof NonNullable<typeof defaults>]??""} placeholder={f.placeholder} rows={3} maxLength={SERVICE_OFFER_MAX_LENGTH} className="rounded-xl border border-slate-200 bg-slate-50 p-3 text-sm font-normal leading-6 focus:outline-sky-500"/></label>)}</div></section>;}
